   227	
   228	static exr_result_t
   229	validate_image_dimensions (
   230	    struct _internal_exr_context* f, struct _internal_exr_part* curpart)
   231	{
   232	    // sanity check the various parts...
   233	    const int64_t          kLargeVal = (int64_t) (INT32_MAX / 2);
   234	    const exr_attr_box2i_t dw        = curpart->data_window;
   235	    const exr_attr_box2i_t dspw      = curpart->display_window;
   236	    int64_t                w, h;
   237	    float                  par, sww;
   238	    int                    maxw = f->max_image_w;
   239	    int                    maxh = f->max_image_h;
   240	
   241	    par = curpart->pixelAspectRatio->f;
   242	    sww = curpart->screenWindowWidth->f;
   243	
   244	    w = (int64_t) dw.max.x - (int64_t) dw.min.x + 1;
   245	    h = (int64_t) dw.max.y - (int64_t) dw.min.y + 1;
   246	
   247	    if (dspw.min.x > dspw.max.x || dspw.min.y > dspw.max.y ||
   248	        dspw.min.x <= -kLargeVal || dspw.min.y <= -kLargeVal ||
   249	        dspw.max.x >= kLargeVal || dspw.max.y >= kLargeVal)
   250	        return f->print_error (
   251	            f,
   252	            EXR_ERR_INVALID_ATTR,
   253	            "Invalid display window (%d, %d - %d, %d)",
   254	            dspw.min.x,
   255	            dspw.min.y,
   256	            dspw.max.x,
   257	            dspw.max.y);
   258	
   259	    if (dw.min.x > dw.max.x || dw.min.y > dw.max.y || dw.min.x <= -kLargeVal ||
   260	        dw.min.y <= -kLargeVal || dw.max.x >= kLargeVal ||
   261	        dw.max.y >= kLargeVal)
   262	        return f->print_error (
   263	            f,
   264	            EXR_ERR_INVALID_ATTR,
   265	            "Invalid data window (%d, %d - %d, %d)",
   266	            dw.min.x,
   267	            dw.min.y,
   268	            dw.max.x,
   269	            dw.max.y);
   270	
   271	    if (maxw > 0 && maxw < w)
   272	        return f->print_error (
   273	            f,
   274	            EXR_ERR_INVALID_ATTR,
   275	            "Invalid width (%" PRId64 ") too large (max %d)",
   276	            w,
   277	            maxw);
   278	
   279	    if (maxh > 0 && maxh < h)
   280	        return f->print_error (
   281	            f,
   282	            EXR_ERR_INVALID_ATTR,
   283	            "Invalid height (%" PRId64 ") too large (max %d)",
   284	            h,
   285	            maxh);
   286	
   287	    if (maxw > 0 && maxh > 0)
   288	    {
   289	        int64_t maxNum = (int64_t) maxw * (int64_t) maxh;
   290	        int64_t ccount = 0;
   291	        if (curpart->chunkCount) ccount = (int64_t) curpart->chunk_count;
   292	        if (ccount > maxNum)
   293	            return f->print_error (
   294	                f,
   295	                EXR_ERR_INVALID_ATTR,
   296	                "Invalid chunkCount (%" PRId64
   297	                ") exceeds maximum area of %" PRId64 "",
   298	                ccount,
   299	                maxNum);
   300	    }
   301	
   302	    /* isnormal will return true when par is 0, which should also be disallowed */
   303	    if (!isnormal (par) || par < 1e-6f || par > 1e+6f)
   304	        return f->print_error (
   305	            f,
   306	            EXR_ERR_INVALID_ATTR,
   307	            "Invalid pixel aspect ratio %g",
   308	            (double) par);
   309	
